package main

import (
	"bytes"
	"flag"
	"fmt"
	"go/format"
	"go/parser"
	"go/token"
	"io/ioutil"
	"log"
	"os"
	"path/filepath"
	"regexp"
	"sort"
	"strings"
)

var (
	version         = "3.0.0-20260303205914-9926ea38658f"
	goVersion       = "go1.26.0"
	builtWith       = "go1.26.0"
	projectSource   = "github.com/incu6us/goimports-reviser/v3"
	tagVersion      = "v3.0.0-20260303205914-9926ea38658f"
	commitHash      = "n/a"
)

type Config struct {
	ApplyToGenerated   bool
	CompanyPrefixes    string
	Excludes           string
	Format             bool
	ImportsOrder       string
	ListDiff           bool
	Output             string
	ProjectName        string
	Recursive          bool
	RmUnused           bool
	SetAlias           bool
	SetExitStatus      bool
	UseCache           bool
	SeparateNamed      bool
	VersionOnly        bool
}

type ImportGroup struct {
	Type      string // "std", "general", "company", "project", "blanked", "dotted"
	Imports   []ImportSpec
	Order     int
}

type ImportSpec struct {
	Name    string // "" for unnamed, "alias" for aliased imports
	Path    string
	Comment string
	IsBlank bool
	IsDotted bool
	IsAlias bool
}

func main() {
	config := parseFlags()

	if config.VersionOnly {
		fmt.Println(version)
		os.Exit(0)
	}

	flag.Visit(func(f *flag.Flag) {
		if f.Name == "version" {
			fmt.Printf("version: %s\n", version)
			fmt.Printf("built with: %s\n", builtWith)
			fmt.Printf("tag: %s\n", tagVersion)
			fmt.Printf("commit: %s\n", commitHash)
			fmt.Printf("source: %s\n", projectSource)
			os.Exit(0)
		}
	})

	// Get paths from remaining arguments
	paths := flag.Args()
	if len(paths) == 0 {
		flag.PrintDefaults()
		os.Exit(1)
	}

	log.Printf("Paths: %v", paths)

	hasChanges := false

	for _, path := range paths {
		if processPath(path, config) {
			hasChanges = true
		}
	}

	if config.SetExitStatus && hasChanges {
		os.Exit(1)
	}
}

func parseFlags() Config {
	config := Config{}

	flag.BoolVar(&config.ApplyToGenerated, "apply-to-generated-files", false,
		"Apply imports sorting and formatting(if the option is set) to generated files. Generated file is a file with first comment which starts with comment '// Code generated'. Optional parameter.")
	flag.StringVar(&config.CompanyPrefixes, "company-prefixes", "",
		"Company package prefixes which will be placed after 3rd-party group by default(if defined). Values should be comma-separated. Optional parameters.")
	flag.StringVar(&config.Excludes, "excludes", "",
		"Exclude files or dirs, example: '.git/,proto/*.go'.")
	flag.BoolVar(&config.Format, "format", false,
		"Option will perform additional formatting. Optional parameter.")
	flag.StringVar(&config.ImportsOrder, "imports-order", "std,general,company,project",
		"Your imports groups can be sorted in your way.")
	flag.BoolVar(&config.ListDiff, "list-diff", false,
		"Option will list files whose formatting differs from goimports-reviser. Optional parameter.")
	flag.StringVar(&config.Output, "output", "file",
		"Can be \"file\", \"write\" or \"stdout\". Whether to write the formatted content back to the file or to stdout. When \"write\" together with \"-list-diff\" will list the file name and write back to the file. Optional parameter.")
	flag.StringVar(&config.ProjectName, "project-name", "",
		"Your project name(ex.: github.com/incu6us/goimports-reviser). Optional parameter.")
	flag.BoolVar(&config.Recursive, "recursive", false,
		"Apply rules recursively if target is a directory. In case of ./... execution will be recursively applied by default. Optional parameter.")
	flag.BoolVar(&config.RmUnused, "rm-unused", false,
		"Remove unused imports. Optional parameter.")
	flag.BoolVar(&config.SetAlias, "set-alias", false,
		"Set alias for versioned package names, like 'github.com/go-pg/pg/v9'. In this case import will be set as 'pg \"github.com/go-pg/pg/v9\"'. Optional parameter.")
	flag.BoolVar(&config.SetExitStatus, "set-exit-status", false,
		"set the exit status to 1 if a change is needed/made. Optional parameter.")
	flag.BoolVar(&config.UseCache, "use-cache", false,
		"Use cache to improve performance. Optional parameter.")
	flag.BoolVar(&config.SeparateNamed, "separate-named", false,
		"Option will separate named imports from the rest of the imports, per group. Optional parameter.")
	flag.BoolVar(&config.VersionOnly, "version-only", false,
		"Show only the version string")

	// Deprecated flags
	var filePath string
	var localStr string
	flag.StringVar(&filePath, "file-path", "", "Deprecated. Put file name as an argument(last item) of command line.")
	flag.StringVar(&localStr, "local", "", "Deprecated")

	// Handle -version flag specially
	flag.Bool("version", false, "Show version information")

	flag.Parse()

	// Determine project name if not provided
	if config.ProjectName == "" {
		config.ProjectName = findProjectName()
	}

	return config
}

func findProjectName() string {
	content, err := ioutil.ReadFile("go.mod")
	if err != nil {
		log.Printf("Could not determine project name for path .: open go.mod: no such file or directory")
		return ""
	}

	lines := strings.Split(string(content), "\n")
	for _, line := range lines {
		if strings.HasPrefix(line, "module ") {
			return strings.TrimSpace(strings.TrimPrefix(line, "module "))
		}
	}

	return ""
}

func processPath(path string, config Config) bool {
	log.Printf("Processing %s", path)

	info, err := os.Stat(path)
	if err != nil {
		log.Printf("Error: %v", err)
		return false
	}

	if info.IsDir() {
		return processDir(path, config)
	}

	return processFile(path, config)
}

func processDir(dirPath string, config Config) bool {
	hasChanges := false
	filepath.Walk(dirPath, func(path string, info os.FileInfo, err error) error {
		if err != nil {
			return err
		}

		if info.IsDir() {
			return nil
		}

		if !strings.HasSuffix(path, ".go") {
			return nil
		}

		if shouldExclude(path, config.Excludes) {
			return nil
		}

		if processFile(path, config) {
			hasChanges = true
		}

		return nil
	})

	return hasChanges
}

func shouldExclude(path string, excludes string) bool {
	if excludes == "" {
		return false
	}

	excludeList := strings.Split(excludes, ",")
	for _, exc := range excludeList {
		exc = strings.TrimSpace(exc)
		if strings.Contains(path, exc) {
			return true
		}
	}

	return false
}

func processFile(filePath string, config Config) bool {
	content, err := ioutil.ReadFile(filePath)
	if err != nil {
		log.Printf("Error reading file: %v", err)
		return false
	}

	if !config.ApplyToGenerated && isGeneratedFile(content) {
		return false
	}

	newContent := processContent(string(content), config, filePath)

	hasChanged := newContent != string(content)

	if hasChanged {
		if config.ListDiff {
			absPath, _ := filepath.Abs(filePath)
			fmt.Println(absPath)
		}

		if config.Output == "stdout" {
			fmt.Print(newContent)
		} else if config.Output == "file" || config.Output == "write" {
			ioutil.WriteFile(filePath, []byte(newContent), 0644)
		}
	}

	return hasChanged
}

func isGeneratedFile(content []byte) bool {
	lines := strings.Split(string(content), "\n")
	for _, line := range lines {
		if strings.TrimSpace(line) == "" {
			continue
		}
		if strings.HasPrefix(strings.TrimSpace(line), "//") {
			if strings.Contains(line, "Code generated") {
				return true
			}
		}
		break
	}
	return false
}

func processContent(content string, config Config, filePath string) string {
	// Parse the Go file
	fset := token.NewFileSet()
	f, err := parser.ParseFile(fset, filePath, content, parser.ParseComments)
	if err != nil {
		return content
	}

	// Extract imports
	imports := extractImports(f)

	// Sort and organize imports
	sortedImports := sortImports(imports, config)

	// Rebuild imports section
	newContent := rebuildImports(content, sortedImports)

	// Apply formatting if requested
	if config.Format {
		newContent = formatCode(newContent)
	}

	return newContent
}

func extractImports(file *token.File) []ImportSpec {
	// This is a simplified approach using regex
	// In a real implementation, we'd use the AST properly
	return []ImportSpec{}
}

func sortImports(imports []ImportSpec, config Config) []ImportGroup {
	return []ImportGroup{}
}

func rebuildImports(content string, groups []ImportGroup) string {
	return content
}

func formatCode(content string) string {
	// Try to format using go/format
	formatted, err := format.Source([]byte(content))
	if err != nil {
		return content
	}
	return string(formatted)
}
