		} else if isProjectDep(imp.Path, config.ProjectName) {
			groupName = "project"
		} else if isCompanyDep(imp.Path, companyPrefixes) && config.CompanyPrefixes != "" {
			groupName = "company"
		} else {
			groupName = "general"
		}

		if _, exists := groups[groupName]; !exists {
			groups[groupName] = []ImportInfo{}
		}
		groups[groupName] = append(groups[groupName], imp)
	}

	// Sort within each group
	for groupName, groupImports := range groups {
		sort.Slice(groupImports, func(i, j int) bool {
			return groupImports[i].Path < groupImports[j].Path
		})
		groups[groupName] = groupImports
	}

	return groups
}

func isStdLib(path string) bool {
	// Check if it's a standard library import
	if !strings.Contains(path, "/") {
		return true
	}
	if strings.HasPrefix(path, "golang.org/x/") {
		return true
	}
	return false
}

func isProjectDep(path, projectName string) bool {
	if projectName == "" {
		return false
	}
	return strings.HasPrefix(path, projectName)
}

func isCompanyDep(path string, prefixes []string) bool {
	for _, prefix := range prefixes {
		if prefix != "" && strings.HasPrefix(path, prefix) {
			return true
		}
	}
	return false
}

func generateImportBlock(groups map[string][]ImportInfo, config Config) string {
	var buf bytes.Buffer
	buf.WriteString("import (\n")

	orderSlice := strings.Split(config.ImportsOrder, ",")

	firstGroup := true
	for _, groupName := range orderSlice {
		groupName = strings.TrimSpace(groupName)
		groupImports, exists := groups[groupName]
		if !exists || len(groupImports) == 0 {
			continue
		}

		// Add blank line between groups
		if !firstGroup {
			buf.WriteString("\n")
		}
		firstGroup = false

		// Separate named imports if requested
		if config.SeparateNamed {
			var unnamed []ImportInfo
			var named []ImportInfo

			for _, imp := range groupImports {
				if imp.Name != "" || imp.IsBlank || imp.IsDot {
					named = append(named, imp)
				} else {
					unnamed = append(unnamed, imp)
				}
			}

			// Write unnamed imports first
			for _, imp := range unnamed {
				buf.WriteString(formatImportLine(imp))
				buf.WriteString("\n")
			}

			// Add blank line before named imports
			if len(unnamed) > 0 && len(named) > 0 {
				buf.WriteString("\n")
			}

			// Write named imports
			for _, imp := range named {
				buf.WriteString(formatImportLine(imp))
				buf.WriteString("\n")
			}
		} else {
			// Write all imports in group
			for _, imp := range groupImports {
				buf.WriteString(formatImportLine(imp))
				buf.WriteString("\n")
			}
		}
	}

	buf.WriteString(")")
	return buf.String()
}

func formatImportLine(imp ImportInfo) string {
	var line string

	if imp.IsBlank {
		line = fmt.Sprintf("\t_ \"%s\"", imp.Path)
	} else if imp.IsDot {
		line = fmt.Sprintf("\t. \"%s\"", imp.Path)
	} else if imp.Name != "" {
		line = fmt.Sprintf("\t%s \"%s\"", imp.Name, imp.Path)
	} else {
		line = fmt.Sprintf("\t\"%s\"", imp.Path)
	}

	if imp.Comment != "" {
		line = line + " " + imp.Comment
	}

	return line
}

func replaceImportSection(content string, newImportBlock string) string {
	// Find the import section and replace it
	lines := strings.Split(content, "\n")
	var result []string
	inImport := false
	importStartIdx := -1
	importEndIdx := -1

	for i, line := range lines {
		trimmed := strings.TrimSpace(line)

		if !inImport && strings.HasPrefix(trimmed, "import") {
			inImport = true
			importStartIdx = i
			if strings.HasPrefix(trimmed, "import (") {
				// Multi-line import
				continue
			} else {
				// Single import line, find where it ends
				for j := i; j < len(lines); j++ {
					if strings.Contains(lines[j], "\"") && !strings.Contains(lines[j+1:j+2] == nil || lines[j+1:j+2][0], "import") {
						importEndIdx = j
						break
					}
				}
				if importEndIdx == -1 {
					importEndIdx = i
				}
				break
			}
		}

		if inImport && strings.TrimSpace(line) == ")" {
			importEndIdx = i
			break
		}
	}

	if importStartIdx == -1 {
		// No import section found, add it
		result = append(result, lines...)
	} else {
		// Replace the import section
		for i := 0; i < importStartIdx; i++ {
			result = append(result, lines[i])
		}
		result = append(result, newImportBlock)
		for i := importEndIdx + 1; i < len(lines); i++ {
			result = append(result, lines[i])
		}
	}

	return strings.Join(result, "\n")
}
