		if strings.HasPrefix(line, "module ") {
			return strings.TrimSpace(strings.TrimPrefix(line, "module "))
		}
	}

	return ""
}

func processPath(path string, config Config) bool {
	log.Printf("Processing %s", path)

	info, err := os.Stat(path)
	if err != nil {
		return false
	}

	if info.IsDir() {
		return processDir(path, config)
	}

	return processFile(path, config)
}

func processDir(dirPath string, config Config) bool {
	hasChanges := false
	filepath.Walk(dirPath, func(path string, info os.FileInfo, err error) error {
		if err != nil {
			return err
		}

		if info.IsDir() {
			return nil
		}

		if !strings.HasSuffix(path, ".go") {
			return nil
		}

		if shouldExclude(path, config.Excludes) {
			return nil
		}

		if processFile(path, config) {
			hasChanges = true
		}

		return nil
	})

	return hasChanges
}

func shouldExclude(path string, excludes string) bool {
	if excludes == "" {
		return false
	}

	excludeList := strings.Split(excludes, ",")
	for _, exc := range excludeList {
		exc = strings.TrimSpace(exc)
		if strings.Contains(path, exc) {
			return true
		}
	}

	return false
}

func processFile(filePath string, config Config) bool {
	content, err := ioutil.ReadFile(filePath)
	if err != nil {
		return false
	}

	if !config.ApplyToGenerated && isGeneratedFile(content) {
		return false
	}

	newContent := processGoFile(string(content), config)

	hasChanged := newContent != string(content)

	if hasChanged {
		if config.ListDiff {
			absPath, _ := filepath.Abs(filePath)
			fmt.Println(absPath)
		}

		if config.Output == "stdout" {
			fmt.Print(newContent)
		} else if config.Output == "file" || config.Output == "write" {
			ioutil.WriteFile(filePath, []byte(newContent), 0644)
		}
	}

	return hasChanged
}

func isGeneratedFile(content []byte) bool {
	lines := strings.Split(string(content), "\n")
	for _, line := range lines {
		trimmed := strings.TrimSpace(line)
		if trimmed == "" {
			continue
		}
		if strings.HasPrefix(trimmed, "//") && strings.Contains(line, "Code generated") {
			return true
		}
		break
	}
	return false
}

func processGoFile(content string, config Config) string {
	fset := token.NewFileSet()
	f, err := parser.ParseFile(fset, "", content, parser.ParseComments)
	if err != nil {
		return content
	}

	// Extract and process imports
	newContent := rewriteImports(content, f, fset, config)

	// Apply formatting if requested
	if config.Format {
		formatted, err := format.Source([]byte(newContent))
		if err == nil {
			newContent = string(formatted)
		}
	}

	return newContent
}

func rewriteImports(content string, file *ast.File, fset *token.FileSet, config Config) string {
	if file.Imports == nil || len(file.Imports) == 0 {
		return content
	}

	// Extract import information
	imports := extractImportInfo(file, fset)

	// Sort and organize imports
	sortedImports := sortAndGroupImports(imports, config)

	// Generate new import block
	newImportBlock := generateImportBlock(sortedImports, config)

	// Replace the import section in the content
	return replaceImportSection(content, newImportBlock)
}

func extractImportInfo(file *ast.File, fset *token.FileSet) []ImportInfo {
	var imports []ImportInfo

	for _, decl := range file.Decls {
		genDecl, ok := decl.(*ast.GenDecl)
		if !ok || genDecl.Tok != token.IMPORT {
			continue
		}

		for _, spec := range genDecl.Specs {
			importSpec := spec.(*ast.ImportSpec)
			path := strings.Trim(importSpec.Path.Value, "\"")
			name := ""
			isBlank := false
			isDot := false

			if importSpec.Name != nil {
				if importSpec.Name.Name == "_" {
					isBlank = true
				} else if importSpec.Name.Name == "." {
					isDot = true
				} else {
					name = importSpec.Name.Name
				}
			}

			comment := ""
			if importSpec.Comment != nil {
				comment = importSpec.Comment.Text()
			}

			imports = append(imports, ImportInfo{
				Name:    name,
				Path:    path,
				Comment: comment,
				IsBlank: isBlank,
				IsDot:   isDot,
			})
		}
	}

	return imports
}

func sortAndGroupImports(imports []ImportInfo, config Config) map[string][]ImportInfo {
	groups := make(map[string][]ImportInfo)
	orderSlice := strings.Split(config.ImportsOrder, ",")

	for _, order := range orderSlice {
		order = strings.TrimSpace(order)
		groups[order] = []ImportInfo{}
	}

	companyPrefixes := strings.Split(config.CompanyPrefixes, ",")
	for i, p := range companyPrefixes {
		companyPrefixes[i] = strings.TrimSpace(p)
	}

	for _, imp := range imports {
		var groupName string

		if imp.IsBlank {
			groupName = "blanked"
		} else if imp.IsDot {
			groupName = "dotted"
		} else if isStdLib(imp.Path) {
			groupName = "std"
		} else if isProjectDep(imp.Path, config.ProjectName) {
			groupName = "project"
		} else if isCompanyDep(imp.Path, companyPrefixes) && config.CompanyPrefixes != "" {
			groupName = "company"
		} else {
			groupName = "general"
		}

		if _, exists := groups[groupName]; !exists {
			groups[groupName] = []ImportInfo{}
		}
		groups[groupName] = append(groups[groupName], imp)
	}

	// Sort within each group
	for groupName, groupImports := range groups {
		sort.Slice(groupImports, func(i, j int) bool {
			return groupImports[i].Path < groupImports[j].Path
		})
		groups[groupName] = groupImports
	}

	return groups
}

func isStdLib(path string) bool {
	// Check if it's a standard library import
	if !strings.Contains(path, "/") {
		return true
	}
	if strings.HasPrefix(path, "golang.org/x/") {
		return true
	}
	return false
}

func isProjectDep(path, projectName string) bool {
	if projectName == "" {
		return false
	}
	return strings.HasPrefix(path, projectName)
}

func isCompanyDep(path string, prefixes []string) bool {
	for _, prefix := range prefixes {
		if prefix != "" && strings.HasPrefix(path, prefix) {
			return true
		}
	}
	return false
}

func generateImportBlock(groups map[string][]ImportInfo, config Config) string {
	var buf bytes.Buffer
	buf.WriteString("import (\n")

	orderSlice := strings.Split(config.ImportsOrder, ",")

	firstGroup := true
	for _, groupName := range orderSlice {
		groupName = strings.TrimSpace(groupName)
		groupImports, exists := groups[groupName]
		if !exists || len(groupImports) == 0 {
			continue
		}

		// Add blank line between groups
		if !firstGroup {
			buf.WriteString("\n")
		}
		firstGroup = false

		// Separate named imports if requested
		if config.SeparateNamed {
			var unnamed []ImportInfo
			var named []ImportInfo

			for _, imp := range groupImports {
				if imp.Name != "" || imp.IsBlank || imp.IsDot {
					named = append(named, imp)
				} else {
					unnamed = append(unnamed, imp)
				}
			}

			// Write unnamed imports first
			for _, imp := range unnamed {
				buf.WriteString(formatImportLine(imp))
				buf.WriteString("\n")
			}

			// Add blank line before named imports
			if len(unnamed) > 0 && len(named) > 0 {
				buf.WriteString("\n")
			}

			// Write named imports
			for _, imp := range named {
				buf.WriteString(formatImportLine(imp))
				buf.WriteString("\n")
			}
		} else {
			// Write all imports in group
			for _, imp := range groupImports {
				buf.WriteString(formatImportLine(imp))
				buf.WriteString("\n")
			}
		}
	}

	buf.WriteString(")")
	return buf.String()
}

func formatImportLine(imp ImportInfo) string {
	var line string

	if imp.IsBlank {
		line = fmt.Sprintf("\t_ \"%s\"", imp.Path)
	} else if imp.IsDot {
		line = fmt.Sprintf("\t. \"%s\"", imp.Path)
	} else if imp.Name != "" {
		line = fmt.Sprintf("\t%s \"%s\"", imp.Name, imp.Path)
	} else {
		line = fmt.Sprintf("\t\"%s\"", imp.Path)
	}

	if imp.Comment != "" {
		line = line + " " + imp.Comment
	}

	return line
}

func replaceImportSection(content string, newImportBlock string) string {
	// Find the import section and replace it
	lines := strings.Split(content, "\n")
	var result []string
	inImport := false
	importStartIdx := -1
	importEndIdx := -1

	for i, line := range lines {
		trimmed := strings.TrimSpace(line)

		if !inImport && strings.HasPrefix(trimmed, "import") {
			inImport = true
			importStartIdx = i
			if strings.HasPrefix(trimmed, "import (") {
				// Multi-line import
				continue
			} else {
				// Single import line, find where it ends
				for j := i; j < len(lines); j++ {
					if strings.Contains(lines[j], "\"") && !strings.Contains(lines[j+1:j+2] == nil || lines[j+1:j+2][0], "import") {
						importEndIdx = j
						break
					}
				}
				if importEndIdx == -1 {
					importEndIdx = i
				}
				break
			}
		}

		if inImport && strings.TrimSpace(line) == ")" {
			importEndIdx = i
			break
		}
	}

	if importStartIdx == -1 {
		// No import section found, add it
		result = append(result, lines...)
	} else {
		// Replace the import section
		for i := 0; i < importStartIdx; i++ {
			result = append(result, lines[i])
		}
		result = append(result, newImportBlock)
		for i := importEndIdx + 1; i < len(lines); i++ {
			result = append(result, lines[i])
		}
	}

	return strings.Join(result, "\n")
