func extractImports(specs []*ast.ImportSpec, config Config) []ImportLine {
	var imports []ImportLine
	companyPrefixes := strings.Split(config.CompanyPrefixes, ",")
	for i, p := range companyPrefixes {
		companyPrefixes[i] = strings.TrimSpace(p)
	}

	for _, spec := range specs {
		path := strings.Trim(spec.Path.Value, "\"")
		name := ""

		if spec.Name != nil {
			name = spec.Name.Name
		}

		comment := ""
		if spec.Comment != nil {
			comment = spec.Comment.Text()
		}

		group := determineGroup(path, name, config.ProjectName, companyPrefixes, config.CompanyPrefixes != "")

		imports = append(imports, ImportLine{
			Name:    name,
			Path:    path,
			Comment: comment,
			Group:   group,
		})
	}

	return imports
}

func determineGroup(path, name, projectName string, companyPrefixes []string, hasCompanyPrefixes bool) string {
	if name == "_" {
		return "blanked"
	}
	if name == "." {
		return "dotted"
	}
	if isStdLib(path) {
		return "std"
	}
	if isProjectDep(path, projectName) {
		return "project"
	}
	if hasCompanyPrefixes && isCompanyDep(path, companyPrefixes) {
		return "company"
	}
	return "general"
}

func isStdLib(path string) bool {
	if !strings.Contains(path, "/") {
		return true
	}
	if strings.HasPrefix(path, "golang.org/x/") {
		return true
	}
	return false
}

func isProjectDep(path, projectName string) bool {
	if projectName == "" {
		return false
	}
	return strings.HasPrefix(path, projectName)
}

func isCompanyDep(path string, prefixes []string) bool {
	for _, prefix := range prefixes {
		if prefix != "" && strings.HasPrefix(path, prefix) {
			return true
		}
	}
	return false
}

func groupAndSortImports(imports []ImportLine, config Config) map[string][]ImportLine {
	groups := make(map[string][]ImportLine)
	orderSlice := strings.Split(config.ImportsOrder, ",")

	for _, order := range orderSlice {
		order = strings.TrimSpace(order)
		groups[order] = []ImportLine{}
	}

	for _, imp := range imports {
		if _, exists := groups[imp.Group]; !exists {
			groups[imp.Group] = []ImportLine{}
		}
		groups[imp.Group] = append(groups[imp.Group], imp)
	}

	// Sort within each group
	for groupName, groupImports := range groups {
		sort.Slice(groupImports, func(i, j int) bool {
			return groupImports[i].Path < groupImports[j].Path
		})
		groups[groupName] = groupImports
	}

	return groups
}

func buildImportBlock(groups map[string][]ImportLine, config Config) []string {
	var lines []string
	lines = append(lines, "import (")

	orderSlice := strings.Split(config.ImportsOrder, ",")

	firstNonEmpty := true
	for _, groupName := range orderSlice {
		groupName = strings.TrimSpace(groupName)
		groupImports, exists := groups[groupName]
		if !exists || len(groupImports) == 0 {
			continue
		}

		// Add blank line before group (except for first group)
		if !firstNonEmpty {
			lines = append(lines, "")
		}
		firstNonEmpty = false

		// Separate named imports if requested
		if config.SeparateNamed {
			var unnamed []ImportLine
			var named []ImportLine

			for _, imp := range groupImports {
				if imp.Name != "" {
					named = append(named, imp)
				} else {
					unnamed = append(unnamed, imp)
				}
			}

			// Add unnamed imports first
			for _, imp := range unnamed {
				lines = append(lines, formatImportLine(imp))
			}

			// Add blank line before named imports
			if len(unnamed) > 0 && len(named) > 0 {
				lines = append(lines, "")
			}

			// Add named imports
			for _, imp := range named {
				lines = append(lines, formatImportLine(imp))
			}
		} else {
			// Add all imports in group
			for _, imp := range groupImports {
				lines = append(lines, formatImportLine(imp))
			}
		}
	}

	lines = append(lines, ")")

	return lines
}

func formatImportLine(imp ImportLine) string {
	var line string

	if imp.Name == "_" {
		line = fmt.Sprintf("\t_ \"%s\"", imp.Path)
	} else if imp.Name == "." {
		line = fmt.Sprintf("\t. \"%s\"", imp.Path)
	} else if imp.Name != "" {
		line = fmt.Sprintf("\t%s \"%s\"", imp.Name, imp.Path)
	} else {
		line = fmt.Sprintf("\t\"%s\"", imp.Path)
	}

	if imp.Comment != "" {
		line = line + " " + imp.Comment
	}

	return line
}
