package main

import (
	"flag"
	"fmt"
	"go/ast"
	"go/format"
	"go/parser"
	"go/token"
	"io/ioutil"
	"log"
	"os"
	"path/filepath"
	"sort"
	"strings"
)

var (
	version       = "3.0.0-20260303205914-9926ea38658f"
	builtWith     = "go1.26.0"
	projectSource = "github.com/incu6us/goimports-reviser/v3"
	tagVersion    = "v3.0.0-20260303205914-9926ea38658f"
	commitHash    = "n/a"
)

type Config struct {
	ApplyToGenerated bool
	CompanyPrefixes  string
	Excludes         string
	Format           bool
	ImportsOrder     string
	ListDiff         bool
	Output           string
	ProjectName      string
	Recursive        bool
	RmUnused         bool
	SetAlias         bool
	SetExitStatus    bool
	UseCache         bool
	SeparateNamed    bool
	VersionOnly      bool
}

type ImportLine struct {
	Name    string // "", "alias", "_", "."
	Path    string
	Comment string
	Group   string
}

func main() {
	config := parseFlags()

	if config.VersionOnly {
		fmt.Println(version)
		os.Exit(0)
	}

	// Check for -version flag
	versionFlagSet := false
	flag.Visit(func(f *flag.Flag) {
		if f.Name == "version" {
			versionFlagSet = true
		}
	})
	if versionFlagSet {
		fmt.Printf("version: %s\n", version)
		fmt.Printf("built with: %s\n", builtWith)
		fmt.Printf("tag: %s\n", tagVersion)
		fmt.Printf("commit: %s\n", commitHash)
		fmt.Printf("source: %s\n", projectSource)
		os.Exit(0)
	}

	paths := flag.Args()
	if len(paths) == 0 {
		flag.PrintDefaults()
		os.Exit(1)
	}

	log.Printf("Paths: %v", paths)

	if config.ProjectName == "" {
		config.ProjectName = findProjectName()
	}

	hasChanges := false
	for _, path := range paths {
		if processPath(path, config) {
			hasChanges = true
		}
	}

	if config.SetExitStatus && hasChanges {
		os.Exit(1)
	}
}

func parseFlags() Config {
	config := Config{}

	flag.BoolVar(&config.ApplyToGenerated, "apply-to-generated-files", false, "")
	flag.StringVar(&config.CompanyPrefixes, "company-prefixes", "", "")
	flag.StringVar(&config.Excludes, "excludes", "", "")
	flag.BoolVar(&config.Format, "format", false, "")
	flag.StringVar(&config.ImportsOrder, "imports-order", "std,general,company,project", "")
	flag.BoolVar(&config.ListDiff, "list-diff", false, "")
	flag.StringVar(&config.Output, "output", "file", "")
	flag.StringVar(&config.ProjectName, "project-name", "", "")
	flag.BoolVar(&config.Recursive, "recursive", false, "")
	flag.BoolVar(&config.RmUnused, "rm-unused", false, "")
	flag.BoolVar(&config.SetAlias, "set-alias", false, "")
	flag.BoolVar(&config.SetExitStatus, "set-exit-status", false, "")
	flag.BoolVar(&config.UseCache, "use-cache", false, "")
	flag.BoolVar(&config.SeparateNamed, "separate-named", false, "")
	flag.BoolVar(&config.VersionOnly, "version-only", false, "")

	// Deprecated flags
	var filePath string
	var localStr string
	flag.StringVar(&filePath, "file-path", "", "")
	flag.StringVar(&localStr, "local", "", "")

	// Handle -version flag specially
	flag.Bool("version", false, "")

	flag.Parse()
	return config
}

func findProjectName() string {
	content, err := ioutil.ReadFile("go.mod")
	if err != nil {
		return ""
	}

	lines := strings.Split(string(content), "\n")
	for _, line := range lines {
		if strings.HasPrefix(line, "module ") {
			return strings.TrimSpace(strings.TrimPrefix(line, "module "))
		}
	}

	return ""
}

func processPath(path string, config Config) bool {
	log.Printf("Processing %s", path)

	info, err := os.Stat(path)
	if err != nil {
		return false
	}

	if info.IsDir() {
		return processDir(path, config)
	}

	return processFile(path, config)
}

func processDir(dirPath string, config Config) bool {
	hasChanges := false
	filepath.Walk(dirPath, func(path string, info os.FileInfo, err error) error {
		if err != nil {
			return err
		}

		if info.IsDir() {
			return nil
		}

		if !strings.HasSuffix(path, ".go") {
			return nil
		}

		if shouldExclude(path, config.Excludes) {
			return nil
		}

		if processFile(path, config) {
			hasChanges = true
		}

		return nil
	})

	return hasChanges
}

func shouldExclude(path string, excludes string) bool {
	if excludes == "" {
		return false
	}

	excludeList := strings.Split(excludes, ",")
	for _, exc := range excludeList {
		exc = strings.TrimSpace(exc)
		if strings.Contains(path, exc) {
			return true
		}
	}

	return false
}

