func buildImportBlock(groups map[string][]ImportLine, config Config) []string {
	var lines []string
	lines = append(lines, "import (")

	orderSlice := strings.Split(config.ImportsOrder, ",")

	firstNonEmpty := true
	for _, groupName := range orderSlice {
		groupName = strings.TrimSpace(groupName)
		groupImports, exists := groups[groupName]
		if !exists || len(groupImports) == 0 {
			continue
		}

		// Add blank line before group (except for first group)
		if !firstNonEmpty {
			lines = append(lines, "")
		}
		firstNonEmpty = false

		// Separate named imports if requested
		if config.SeparateNamed {
			var unnamed []ImportLine
			var named []ImportLine

			for _, imp := range groupImports {
				if imp.Name != "" {
					named = append(named, imp)
				} else {
					unnamed = append(unnamed, imp)
				}
			}

			// Add unnamed imports first
			for _, imp := range unnamed {
				lines = append(lines, formatImportLine(imp))
			}

			// Add blank line before named imports
			if len(unnamed) > 0 && len(named) > 0 {
				lines = append(lines, "")
			}

			// Add named imports
			for _, imp := range named {
				lines = append(lines, formatImportLine(imp))
			}
		} else {
			// Add all imports in group
			for _, imp := range groupImports {
				lines = append(lines, formatImportLine(imp))
			}
		}
	}

	lines = append(lines, ")")

	return lines
}

func formatImportLine(imp ImportLine) string {
	var line string

	if imp.Name == "_" {
		line = fmt.Sprintf("\t_ \"%s\"", imp.Path)
	} else if imp.Name == "." {
		line = fmt.Sprintf("\t. \"%s\"", imp.Path)
	} else if imp.Name != "" {
		line = fmt.Sprintf("\t%s \"%s\"", imp.Name, imp.Path)
	} else {
		line = fmt.Sprintf("\t\"%s\"", imp.Path)
	}

	if imp.Comment != "" {
		line = line + " " + imp.Comment
	}

	return line
}
