package main

import (
	"flag"
	"fmt"
	"go/ast"
	"go/format"
	"go/parser"
	"go/token"
	"io/ioutil"
	"log"
	"os"
	"path/filepath"
	"regexp"
	"sort"
	"strings"
)

var (
	version       = "3.0.0-20260303205914-9926ea38658f"
	builtWith     = "go1.26.0"
	projectSource = "github.com/incu6us/goimports-reviser/v3"
	tagVersion    = "v3.0.0-20260303205914-9926ea38658f"
	commitHash    = "n/a"
)

type Config struct {
	ApplyToGenerated bool
	CompanyPrefixes  string
	Excludes         string
	Format           bool
	ImportsOrder     string
	ListDiff         bool
	Output           string
	ProjectName      string
	Recursive        bool
	RmUnused         bool
	SetAlias         bool
	SetExitStatus    bool
	UseCache         bool
	SeparateNamed    bool
	VersionOnly      bool
}

type ImportLine struct {
	Name    string // "", "alias", "_", "."
	Path    string
	Comment string
	Group   string
}

func main() {
	config := parseFlags()

	if config.VersionOnly {
		fmt.Println(version)
		os.Exit(0)
	}

	// Check for -version flag
	versionFlagSet := false
	flag.Visit(func(f *flag.Flag) {
		if f.Name == "version" {
			versionFlagSet = true
		}
	})
	if versionFlagSet {
		fmt.Printf("version: %s\n", version)
		fmt.Printf("built with: %s\n", builtWith)
		fmt.Printf("tag: %s\n", tagVersion)
		fmt.Printf("commit: %s\n", commitHash)
		fmt.Printf("source: %s\n", projectSource)
		os.Exit(0)
	}

	paths := flag.Args()
	if len(paths) == 0 {
		flag.PrintDefaults()
		os.Exit(1)
	}

	log.Printf("Paths: %v", paths)

	if config.ProjectName == "" {
		config.ProjectName = findProjectName()
	}

	hasChanges := false
	for _, path := range paths {
		if processPath(path, config) {
			hasChanges = true
		}
	}

	if config.SetExitStatus && hasChanges {
		os.Exit(1)
	}
}

func parseFlags() Config {
	config := Config{}

	flag.BoolVar(&config.ApplyToGenerated, "apply-to-generated-files", false, "")
	flag.StringVar(&config.CompanyPrefixes, "company-prefixes", "", "")
	flag.StringVar(&config.Excludes, "excludes", "", "")
	flag.BoolVar(&config.Format, "format", false, "")
	flag.StringVar(&config.ImportsOrder, "imports-order", "std,general,company,project", "")
	flag.BoolVar(&config.ListDiff, "list-diff", false, "")
	flag.StringVar(&config.Output, "output", "file", "")
	flag.StringVar(&config.ProjectName, "project-name", "", "")
	flag.BoolVar(&config.Recursive, "recursive", false, "")
	flag.BoolVar(&config.RmUnused, "rm-unused", false, "")
	flag.BoolVar(&config.SetAlias, "set-alias", false, "")
	flag.BoolVar(&config.SetExitStatus, "set-exit-status", false, "")
	flag.BoolVar(&config.UseCache, "use-cache", false, "")
	flag.BoolVar(&config.SeparateNamed, "separate-named", false, "")
	flag.BoolVar(&config.VersionOnly, "version-only", false, "")

	// Deprecated flags
	var filePath string
	var localStr string
	flag.StringVar(&filePath, "file-path", "", "")
	flag.StringVar(&localStr, "local", "", "")

	// Handle -version flag specially
	flag.Bool("version", false, "")

	flag.Parse()
	return config
}

func findProjectName() string {
	content, err := ioutil.ReadFile("go.mod")
	if err != nil {
		return ""
	}

	lines := strings.Split(string(content), "\n")
	for _, line := range lines {
		if strings.HasPrefix(line, "module ") {
			return strings.TrimSpace(strings.TrimPrefix(line, "module "))
		}
	}

	return ""
}

func processPath(path string, config Config) bool {
	log.Printf("Processing %s", path)

	info, err := os.Stat(path)
	if err != nil {
		return false
	}

	if info.IsDir() {
		return processDir(path, config)
	}

	return processFile(path, config)
}

func processDir(dirPath string, config Config) bool {
	hasChanges := false
	filepath.Walk(dirPath, func(path string, info os.FileInfo, err error) error {
		if err != nil {
			return err
		}

		if info.IsDir() {
			return nil
		}

		if !strings.HasSuffix(path, ".go") {
			return nil
		}

		if shouldExclude(path, config.Excludes) {
			return nil
		}

		if processFile(path, config) {
			hasChanges = true
		}

		return nil
	})

	return hasChanges
}

func shouldExclude(path string, excludes string) bool {
	if excludes == "" {
		return false
	}

	excludeList := strings.Split(excludes, ",")
	for _, exc := range excludeList {
		exc = strings.TrimSpace(exc)
		if strings.Contains(path, exc) {
			return true
		}
	}

	return false
}

func processFile(filePath string, config Config) bool {
	content, err := ioutil.ReadFile(filePath)
	if err != nil {
		return false
	}

	if !config.ApplyToGenerated && isGeneratedFile(content) {
		return false
	}

	newContent := processGoFile(string(content), config)

	hasChanged := newContent != string(content)

	if hasChanged {
		if config.ListDiff {
			absPath, _ := filepath.Abs(filePath)
			fmt.Println(absPath)
		}

		if config.Output == "stdout" {
			fmt.Print(newContent)
		} else if config.Output == "file" || config.Output == "write" {
			ioutil.WriteFile(filePath, []byte(newContent), 0644)
		}
	}

	return hasChanged
}

func isGeneratedFile(content []byte) bool {
	lines := strings.Split(string(content), "\n")
	for _, line := range lines {
		trimmed := strings.TrimSpace(line)
		if trimmed == "" {
			continue
		}
		if strings.HasPrefix(trimmed, "//") && strings.Contains(line, "Code generated") {
			return true
		}
		break
	}
	return false
}

func processGoFile(content string, config Config) string {
	fset := token.NewFileSet()
	f, err := parser.ParseFile(fset, "", content, parser.ParseComments)
	if err != nil {
		return content
	}

	// Extract and process imports
	newContent := rewriteImports(content, f, fset, config)

	// Apply formatting if requested
	if config.Format {
		formatted, err := format.Source([]byte(newContent))
		if err == nil {
			newContent = string(formatted)
		}
	}

	return newContent
}

func rewriteImports(content string, file *ast.File, fset *token.FileSet, config Config) string {
	if file.Imports == nil || len(file.Imports) == 0 {
		return content
	}

	// Find import block in the source code
	lines := strings.Split(content, "\n")

	// Find import statements in the AST
	var importSpecs []*ast.ImportSpec
	var importGenDecl *ast.GenDecl

	for _, decl := range file.Decls {
		genDecl, ok := decl.(*ast.GenDecl)
		if !ok || genDecl.Tok != token.IMPORT {
			continue
		}
		importGenDecl = genDecl
		for _, spec := range genDecl.Specs {
			if importSpec, ok := spec.(*ast.ImportSpec); ok {
				importSpecs = append(importSpecs, importSpec)
			}
		}
		break
	}

	if importGenDecl == nil || len(importSpecs) == 0 {
		return content
	}

	// Extract import information
	imports := extractImports(importSpecs, config)

	// Group and sort imports
	groups := groupAndSortImports(imports, config)

	// Find where import block starts and ends in the source
	startLine := -1
	endLine := -1

	for i, line := range lines {
		trimmed := strings.TrimSpace(line)
		if trimmed == "import (" || strings.HasPrefix(trimmed, "import \"") || strings.HasPrefix(trimmed, "import `") {
			startLine = i
			if !strings.Contains(trimmed, ")") {
				// Multi-line import
				for j := i + 1; j < len(lines); j++ {
					if strings.TrimSpace(lines[j]) == ")" {
						endLine = j
						break
					}
				}
			} else {
				endLine = i
			}
			break
		}
	}

	if startLine == -1 {
		return content
	}

	// Build new import section
	newImportSection := buildImportBlock(groups, config)

	// Replace the import section
	var newLines []string
	newLines = append(newLines, lines[:startLine]...)
	newLines = append(newLines, newImportSection...)
	newLines = append(newLines, lines[endLine+1:]...)

	return strings.Join(newLines, "\n")
}

func generateAlias(path string) string {
	// Split path by "/"
	parts := strings.Split(path, "/")

	// Look for version patterns (v1, v2, v9, etc.)
	versionRegex := regexp.MustCompile(`^v\d+$`)

	// Find the component before any version component
	for i := len(parts) - 1; i >= 0; i-- {
		if versionRegex.MatchString(parts[i]) {
			// Found a version component, use the previous one as alias
			if i > 0 {
				return parts[i-1]
			}
			break
		}
	}

	// No version found, use the last component
	if len(parts) > 0 {
		return parts[len(parts)-1]
	}

	return ""
}

func extractImports(specs []*ast.ImportSpec, config Config) []ImportLine {
	var imports []ImportLine
	companyPrefixes := strings.Split(config.CompanyPrefixes, ",")
	for i, p := range companyPrefixes {
		companyPrefixes[i] = strings.TrimSpace(p)
	}

	for _, spec := range specs {
		path := strings.Trim(spec.Path.Value, "\"")
		name := ""

		if spec.Name != nil {
			name = spec.Name.Name
		}

		// If SetAlias is true and name is empty, generate an alias for versioned packages
		if config.SetAlias && name == "" {
			alias := generateAlias(path)
			if alias != "" {
				name = alias
			}
		}

		comment := ""
		if spec.Comment != nil {
			// The Comment.Text() includes the "//" prefix in some cases
			rawComment := spec.Comment.Text()
			// Trim and keep only the comment text
			rawComment = strings.TrimSpace(rawComment)
			if strings.HasPrefix(rawComment, "//") {
				comment = rawComment
			} else if rawComment != "" {
				comment = "// " + rawComment
			}
		}

		group := determineGroup(path, name, config.ProjectName, companyPrefixes, config.CompanyPrefixes != "")

		imports = append(imports, ImportLine{
			Name:    name,
			Path:    path,
			Comment: comment,
			Group:   group,
		})
	}

	return imports
}

func determineGroup(path, name, projectName string, companyPrefixes []string, hasCompanyPrefixes bool) string {
	if name == "_" {
		return "blanked"
	}
	if name == "." {
		return "dotted"
	}
	if isStdLib(path) {
		return "std"
	}
	if isProjectDep(path, projectName) {
		return "project"
	}
	if hasCompanyPrefixes && isCompanyDep(path, companyPrefixes) {
		return "company"
	}
	return "general"
}

func isStdLib(path string) bool {
	if !strings.Contains(path, "/") {
		return true
	}
	return false
}

func isProjectDep(path, projectName string) bool {
	if projectName == "" {
		return false
	}
	return strings.HasPrefix(path, projectName)
}

func isCompanyDep(path string, prefixes []string) bool {
	for _, prefix := range prefixes {
		if prefix != "" && strings.HasPrefix(path, prefix) {
			return true
		}
	}
	return false
}

func groupAndSortImports(imports []ImportLine, config Config) map[string][]ImportLine {
	groups := make(map[string][]ImportLine)
	orderSlice := strings.Split(config.ImportsOrder, ",")

	for _, order := range orderSlice {
		order = strings.TrimSpace(order)
		groups[order] = []ImportLine{}
	}

	for _, imp := range imports {
		if _, exists := groups[imp.Group]; !exists {
			groups[imp.Group] = []ImportLine{}
		}
		groups[imp.Group] = append(groups[imp.Group], imp)
	}

	// Sort within each group
	for groupName, groupImports := range groups {
		sort.Slice(groupImports, func(i, j int) bool {
			return groupImports[i].Path < groupImports[j].Path
		})
		groups[groupName] = groupImports
	}

	return groups
}

func buildImportBlock(groups map[string][]ImportLine, config Config) []string {
	var lines []string
	lines = append(lines, "import (")

	orderSlice := strings.Split(config.ImportsOrder, ",")

	firstNonEmpty := true
	for _, groupName := range orderSlice {
		groupName = strings.TrimSpace(groupName)
		groupImports, exists := groups[groupName]
		if !exists || len(groupImports) == 0 {
			continue
		}

		// Add blank line before group (except for first group)
		if !firstNonEmpty {
			lines = append(lines, "")
		}
		firstNonEmpty = false

		// Separate named imports if requested
		if config.SeparateNamed {
			var unnamed []ImportLine
			var named []ImportLine

			for _, imp := range groupImports {
				if imp.Name != "" {
					named = append(named, imp)
				} else {
					unnamed = append(unnamed, imp)
				}
			}

			// Add unnamed imports first
			for _, imp := range unnamed {
				lines = append(lines, formatImportLine(imp))
			}

			// Add blank line before named imports
			if len(unnamed) > 0 && len(named) > 0 {
				lines = append(lines, "")
			}

			// Add named imports
			for _, imp := range named {
				lines = append(lines, formatImportLine(imp))
			}
		} else {
			// Add all imports in group
			for _, imp := range groupImports {
				lines = append(lines, formatImportLine(imp))
			}
		}
	}

	lines = append(lines, ")")

	return lines
}

func formatImportLine(imp ImportLine) string {
	var line string

	if imp.Name == "_" {
		line = fmt.Sprintf("\t_ \"%s\"", imp.Path)
	} else if imp.Name == "." {
		line = fmt.Sprintf("\t. \"%s\"", imp.Path)
	} else if imp.Name != "" {
		line = fmt.Sprintf("\t%s \"%s\"", imp.Name, imp.Path)
	} else {
		line = fmt.Sprintf("\t\"%s\"", imp.Path)
	}

	if imp.Comment != "" {
		line = line + " " + imp.Comment
	}

	return line
}
